import React from "react";

const CTA = () => {
    return (
        <section className="px-8 py-20 bg-blue-600 text-white text-center">
            <div className="max-w-3xl mx-auto">

                <h2 className="text-3xl font-bold">
                    Ready to Optimize Your Infrastructure?
                </h2>

                <p className="mt-3 text-blue-100">
                    Join communities already saving water and costs.
                </p>

                <div className="mt-8 flex justify-center gap-4">
                    <button className="bg-white text-blue-600 px-6 py-3 rounded-lg font-medium hover:bg-gray-100">
                        Request Demo
                    </button>

                    <button className="border border-white px-6 py-3 rounded-lg hover:bg-blue-500">
                        Learn More
                    </button>
                </div>

            </div>
        </section>
    );
};

export default CTA;
